begin;
select plan(2);

select is(
    encode(wedecent_private.checkpoint_event_v2_encoding(
        'finalize', 'device', 'wd_aaaaaaaaaaaaaaaa',
        '11111111-1111-4111-8111-111111111111',
        '22222222-2222-4222-8222-222222222222',
        '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef',
        decode(repeat('11', 32), 'hex'),
        decode('3080ab979e283614fec564a8a112bd6f18fba4508e00f0ceba34c8e75738aa33', 'hex'),
        decode(repeat('33', 32), 'hex'),
        42, 7
    ), 'hex'),
    '',
    'PostgreSQL canonical checkpoint event encoding matches the shared Go vector'
);

select is(
    encode(wedecent_private.checkpoint_event_v2_hash(
        'finalize', 'device', 'wd_aaaaaaaaaaaaaaaa',
        '11111111-1111-4111-8111-111111111111',
        '22222222-2222-4222-8222-222222222222',
        '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef',
        decode(repeat('11', 32), 'hex'),
        decode('3080ab979e283614fec564a8a112bd6f18fba4508e00f0ceba34c8e75738aa33', 'hex'),
        decode(repeat('33', 32), 'hex'),
        42, 7
    ), 'hex'),
    'c1ce98f4710d51dc24a0f93cd1156fd47a656fac946fd825c0b5d3ea4310c0fb',
    'PostgreSQL canonical checkpoint event hash matches the shared Go vector'
);

select * from finish();
rollback;
